public sealed class Document : IDisposable {
    private readonly List<Paragraph> _parts = new();
    private readonly SafeFileHandle _backing;      // owned unmanaged handle
    public Paragraph Add(string text) { var p = new Paragraph(text); _parts.Add(p); return p; }
    public void Dispose() {
        foreach (var p in _parts) p.Dispose();     // cascade to owned parts only
        _backing.Dispose();                        // SafeHandle: no finalizer needed
    }
}
